  let x = real.x;
  let y = real.y;
  let z = real.z;
  let r = real.w;
  let across = vec3f(1.0 - 2.0 * (y * y + z * z), 2.0 * (x * y + r * z), 2.0 * (x * z - r * y)) * scale;
